def test_ias21_cta_and_balance_sheet_equation_with_unrealized_fx(): pnl_var = Decimal('-42.09'); ufx = Decimal('-652.24'); equity_var = Decimal('-512.77'); cta = calculate_currency_translation_adjustment(is_multicurrency=True, pnl_translation_variance=pnl_var, unrealized_fx=ufx, equity_translation_variance=equity_var); assert cta == Decimal('97.38'); totals = calculate_balance_sheet_equation(total_assets=Decimal('25417.10'), total_liabilities=Decimal('0.00'), total_equity=Decimal('20173.72'), net_income=Decimal('5798.24'), unrealized_fx=ufx, net_worth_adjustment=Decimal('0.00'), cta_adjustment=cta); assert totals.equation_delta == Decimal('0.00'); assert totals.is_balanced is True; _m1_cta = calculate_currency_translation_adjustment(is_multicurrency=True, pnl_translation_variance=Decimal('0.00'), unrealized_fx=Decimal('150.00'), equity_translation_variance=Decimal('-50.00')); assert _m1_cta == Decimal('-200.00'); 'AC-reporting.balance-sheet.2'; 'AC-reporting.balance-sheet.2'; _m2_cta = calculate_currency_translation_adjustment(is_multicurrency=True, pnl_translation_variance=Decimal('0.00'), unrealized_fx=Decimal('262.73'), equity_translation_variance=Decimal('0.00')); assert _m2_cta == Decimal('0.00'); 'AC-reporting.balance-sheet.2'; 'AC-reporting.balance-sheet.2'; _m3_cta = calculate_currency_translation_adjustment(is_multicurrency=False, pnl_translation_variance=Decimal('100.00'), unrealized_fx=Decimal('50.00'), equity_translation_variance=Decimal('25.00')); assert _m3_cta == Decimal('0.00')
